-- Date: 14-Nov-2026
-- Description: Current portable Chess video seed; generated by refresh_seeds.py.
-- Purpose: Refresh desired data without deleting omitted records.
-- Usage: Managed plugin deployment; refresh with tools/refresh_seeds.py.
--changeset clive:orac_chess_current_video_2026_11_14 context:plugin,prod labels:plugin runOnChange:true stripComments:false endDelimiter:/
declare
  l_payload clob;
  l_rows json_array_t;
  l_row json_object_t;
  l_links json_array_t;
  l_id number;
  l_version number;
  l_new_version number;
  l_target number;
  l_description clob;
  l_platform varchar2(50);
  l_external varchar2(255);
  l_key varchar2(100);
  function text_value(p_name varchar2) return varchar2 is
  begin
    return l_row.get_string(p_name);
  end;

  procedure append_payload(p_hex varchar2) is
    l_text varchar2(32767);
  begin
    l_text := utl_i18n.raw_to_char(hextoraw(p_hex),'AL32UTF8');
    dbms_lob.writeappend(l_payload,length2(l_text),l_text);
  end;
begin
  dbms_lob.createtemporary(l_payload,true);
  append_payload('');
  append_payload('');
  append_payload('');
  append_payload('');
  append_payload('');
  append_payload('');
  append_payload('');
  append_payload('');
  append_payload('');
  append_payload('');
  l_rows := json_array_t.parse(l_payload);
  for i in 0..l_rows.get_size-1 loop
    l_row := treat(l_rows.get(i) as json_object_t);
    l_platform := text_value('platform');
    l_external := text_value('external_video_id');
    begin
      select video_id,row_version into l_id,l_version from orac_chess.chess_video_v
      where platform=l_platform and external_video_id=l_external;
    exception when no_data_found then
      l_id := null;
      l_description := l_row.get_clob('description');
      orac_chess.chess_admin_api.save_video(l_id,null,text_value('platform'),
        text_value('external_video_id'),text_value('video_url'),text_value('title'),
        text_value('creator'),l_description,l_row.get_number('duration_seconds'),
        to_date(text_value('published_on'),'YYYY-MM-DD"T"HH24:MI:SS'),l_version);
      if dbms_lob.istemporary(l_description)=1 then dbms_lob.freetemporary(l_description); end if;
    end;
    l_links := l_row.get_array('opening_keys');
    for j in 0..l_links.get_size-1 loop
      l_key := l_links.get_string(j);
      select max(opening_id) into l_target from orac_chess.chess_catalogue_entry
      where catalogue_key=l_key and entity_kind='OPENING';
      if l_target is not null then
        declare l_count number;
        begin
          select count(*) into l_count from orac_chess.chess_video_opening_v
          where video_id=l_id and opening_id=l_target;
          if l_count=0 then
            orac_chess.chess_admin_api.link_video_opening(l_id,l_target,l_version,true,l_new_version);
            l_version := l_new_version;
          end if;
        end;
      end if;
    end loop;
    l_links := l_row.get_array('gambit_keys');
    for j in 0..l_links.get_size-1 loop
      l_key := l_links.get_string(j);
      select max(gambit_id) into l_target from orac_chess.chess_catalogue_entry
      where catalogue_key=l_key and entity_kind='GAMBIT';
      if l_target is not null then
        declare l_count number;
        begin
          select count(*) into l_count from orac_chess.chess_video_gambit_v
          where video_id=l_id and gambit_id=l_target;
          if l_count=0 then
            orac_chess.chess_admin_api.link_video_gambit(l_id,l_target,l_version,true,l_new_version);
            l_version := l_new_version;
          end if;
        end;
      end if;
    end loop;
    l_links := l_row.get_array('variation_keys');
    for j in 0..l_links.get_size-1 loop
      l_key := l_links.get_string(j);
      select max(variation_id) into l_target from orac_chess.chess_catalogue_entry
      where catalogue_key=l_key and entity_kind='VARIATION';
      if l_target is not null then
        declare l_count number;
        begin
          select count(*) into l_count from orac_chess.chess_video_variation_v
          where video_id=l_id and variation_id=l_target;
          if l_count=0 then
            orac_chess.chess_admin_api.link_video_variation(l_id,l_target,l_version,true,l_new_version);
            l_version := l_new_version;
          end if;
        end;
      end if;
    end loop;
  end loop;
  dbms_lob.freetemporary(l_payload);
exception when others then
  if dbms_lob.istemporary(l_description)=1 then dbms_lob.freetemporary(l_description); end if;
  if dbms_lob.istemporary(l_payload)=1 then dbms_lob.freetemporary(l_payload); end if;
  raise;
end;
/
-- Retain reference data and user changes on rollback.
--rollback empty
